<?php
require_once __DIR__.'/../app/agent/tool_output.php';require_once __DIR__.'/../app/agent/attachment_manager.php';
function okx($v,$m){if(!$v)throw new RuntimeException($m);}
$e=lac_tool_output_envelope(['ok'=>true,'tool'=>'python_dataframe','execution_id'=>'abc','result_id'=>'res_aaaaaaaaaaaaaaaaaaaaaaaa','result_reference'=>'agent-results/abcdef123456.json','result'=>['rows'=>[['x'=>1]],'columns'=>['x']]],['run_id'=>'r']);
okx($e['schema_version']==='1.0','envelope version');okx($e['result']['type']==='tabular','tabular type');okx($e['result']['data_ref']==='agent-results/abcdef123456.json','Data Pack reference');okx($e['artifacts']===[],'Data Pack must not be mislabeled as a binary artifact');okx($e['status']==='succeeded','success status');okx($e['result_id']==='res_aaaaaaaaaaaaaaaaaaaaaaaa','result identity');
$base=lac_attachment_store_dir();@mkdir($base,0775,true);$a=lac_attachment_register(['conversation_id'=>'c-test','message_id'=>'m-test','source_type'=>'data_pack','source_ref'=>'agent-results/abcdef123456.json','presentation'=>'data_table','mime_type'=>'application/json','title'=>'Table']);
okx($a['schema_version']===2,'attachment schema');okx($a['presentation']==='data_table','presentation');okx($a['source_type']==='data_pack'&&$a['artifact_ref']===null,'Data Pack attachment must not claim an artifact reference');okx(lac_attachment_get($a['attachment_id'],'c-test','m-test')!==null,'owner read');okx(lac_attachment_get($a['attachment_id'],'wrong','m-test')===null,'conversation isolation');okx(count(lac_attachment_list('c-test','m-test'))===1,'message-scoped attachment list');
$independent=lac_attachment_register(['conversation_id'=>'c-test','run_id'=>'run-independent','execution_id'=>'exec-independent','source_type'=>'data_pack','source_ref'=>'agent-results/abcdef123456.json','presentation'=>'data_table','mime_type'=>'application/json','title'=>'Execution result']);
okx($independent['message_id']==='','execution attachment must not require message ownership');
okx(count(lac_attachment_list('c-test',null))===2,'conversation-level registry must include message-independent attachments');
$binaryOnly=lac_attachment_register_tool_result(['ok'=>true,'tool'=>'python_plot','execution_id'=>'plot-exec','result_reference'=>'agent-results/abcdef123456.json','result'=>['file'=>'chart_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.jpg','image_url'=>'api.php?action=python_output&file=chart_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.jpg']],['conversation_id'=>'c-test','run_id'=>'run-plot']);
okx($binaryOnly===[],'binary image results must be presented through their Artifact attachment only');
@unlink($base.'/'.$a['attachment_id'].'.json');@unlink($base.'/'.$independent['attachment_id'].'.json');echo "Tool output and attachment architecture test passed.\n";
